class Solution {
public:
    int findGCD(vector<int>& nums) {
        int mn = nums[0], mx = nums[0];
        for (int x : nums) {
            if (x < mn) mn = x;
            if (x > mx) mx = x;
        }
        while (mn != 0) {
            int t = mn;
            mn = mx % mn;
            mx = t;
        }
        return mx;
    }
};
